"""Basis tests.

Independence rule: the reference for a basis function is a closed form written
out by hand in the test, or an orthonormality integral evaluated by a quadrature
rule that shares no code with the basis.  Never the basis checked against itself.
"""

import numpy as np
import pytest

from altharm.basis import CircularBasis, SphericalBasis, real_sph_harm
from altharm.kpath import sphere_grid, circle


def test_real_sph_harm_against_closed_forms():
    """l <= 2 against formulas written out by hand, not generated by the code."""
    rng = np.random.default_rng(0)
    theta = rng.uniform(0.1, np.pi - 0.1, 40)
    phi = rng.uniform(0.0, 2 * np.pi, 40)
    ct, st = np.cos(theta), np.sin(theta)

    # scipy's lpmv carries the Condon-Shortley phase, so the m>0 forms below
    # carry its sign; that is a convention, and orthonormality is what matters.
    expected = {
        (0, 0): np.full_like(theta, np.sqrt(1.0 / (4 * np.pi))),
        (1, 0): np.sqrt(3.0 / (4 * np.pi)) * ct,
        (1, 1): -np.sqrt(3.0 / (4 * np.pi)) * st * np.cos(phi),
        (1, -1): -np.sqrt(3.0 / (4 * np.pi)) * st * np.sin(phi),
        (2, 0): np.sqrt(5.0 / (16 * np.pi)) * (3 * ct**2 - 1),
        (2, 2): np.sqrt(15.0 / (16 * np.pi)) * st**2 * np.cos(2 * phi),
    }
    for (l, m), ref in expected.items():
        got = real_sph_harm(l, m, theta, phi)
        assert np.allclose(got, ref, atol=1e-12), f"Y_{l}{m} differs from closed form"


def test_spherical_orthonormality_by_quadrature():
    """<Y_lm|Y_l'm'> = delta, integrated by Gauss-Legendre x uniform phi."""
    lmax = 6
    basis = SphericalBasis(lmax)
    pts, w = sphere_grid(ntheta=lmax + 4, nphi=2 * lmax + 4)
    Y = basis.evaluate(pts)
    gram = Y.T @ (w[:, None] * Y)
    assert np.allclose(gram, np.eye(basis.size), atol=1e-10), (
        f"max deviation {np.abs(gram - np.eye(basis.size)).max():.2e}"
    )


def test_sphere_quadrature_weights_sum_to_4pi():
    _, w = sphere_grid(8, 16)
    assert np.isclose(w.sum(), 4 * np.pi, atol=1e-12)


def test_circular_orthogonality():
    """cos/sin harmonics are orthogonal on a uniform circle, norms N/2 (N for l=0)."""
    lmax = 8
    n = 4 * lmax + 8
    basis = CircularBasis(lmax)
    D = basis.evaluate(circle(1.0, n))
    gram = D.T @ D
    off = gram - np.diag(np.diag(gram))
    assert np.abs(off).max() < 1e-9
    diag = np.diag(gram)
    assert np.isclose(diag[0], n)
    assert np.allclose(diag[1:], n / 2.0)


def test_circular_angle_is_cartesian_not_fractional():
    """A circle in a hexagonal cell must still give uniformly spaced angles.

    Reading angles off fractional coordinates would apply the lattice metric and
    bunch them up; this is the concrete bug the module docstring warns about.
    """
    n = 60
    pts = circle(0.4, n)
    t = CircularBasis(1).angles(pts)
    d = np.diff(np.unwrap(t))
    assert np.allclose(d, 2 * np.pi / n, atol=1e-12)


def test_rejects_non_orthogonal_plane():
    with pytest.raises(ValueError):
        CircularBasis(4, e1=(1, 0, 0), e2=(1, 1, 0))


def test_high_l_normalisation_does_not_underflow():
    """l = 40 would overflow a naive (l-m)!/(l+m)!; the log-space form must not."""
    v = real_sph_harm(40, 40, np.array([1.0]), np.array([0.3]))
    assert np.isfinite(v).all()
    pts, w = sphere_grid(48, 96)
    y = real_sph_harm(40, 40, *SphericalBasis(0).angles(pts))
    assert np.isclose(float(y @ (w * y)), 1.0, atol=1e-8)
